#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    static int count;
    string name;
    int fish;

    Cat(string n, int f) : name(n), fish(f) {
        count = count + 1;
    }

    static int howMany() {
        return count;
    }

    void show() const {
        cout << name << " 有 " << fish << " 条" << endl;
    }
};

int Cat::count = 0;

int main() {
    int a = 0;
    int b = 0;
    int c = 0;
    cin >> a >> b >> c;

    Cat c1("小橘", a);
    Cat c2("狸花", b);
    Cat c3("小白", c);
    cout << "一共出生了 " << Cat::howMany() << " 只" << endl;
    c1.show();
    return 0;
}

